# region: intake
def intake(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: shape
def shape(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return shape(sift(render(intake(raw))))

