        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'total': 10, 'flags': ['n', 'total']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'total': 6, 'flags': ['n', 'total']})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'total': 0, 'flags': []})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'total': 24, 'flags': ['n', 'total']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 0, 'flags': ['n']})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 24, 'flags': ['n', 'total']})
